insert into publishers (name) values ('Weaviate') on conflict (name) do nothing; insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Weaviate', 'weaviate', p.id, 'Open-source vector database with hybrid search and cloud offering.', 'Weaviate supports vector and hybrid retrieval for building AI search and RAG systems.', 'https://weaviate.io', 'published', 'Open source', 'Open source / Weaviate Cloud', true, true, true, ARRAY['vector-db', 'hybrid-search', 'oss']::text[], ARRAY['Open-source + cloud', 'Hybrid search']::text[], ARRAY['Ops overhead if self-hosting']::text[], ARRAY['Developers']::text[], current_date from publishers p where p.name = 'Weaviate' on conflict (slug) do nothing;
